"""Where generated files go.

Everything used to land in bare /tmp - /tmp/wigley_hull.usda,
/tmp/mmws_sky.png, /tmp/mmws_run.npz - which is fine on one person's machine
and wrong on a shared one. Two people running the same tool overwrite each
other's hull, and because `capture()` overwrites by design, a run recorded
while someone else was recording silently becomes a mixture of nothing useful.

Resolution order:

  1. $MMWS_OUT, if set. The escape hatch for people sharing one clone of the
     repo, where nothing else can tell them apart.
  2. <repo>/out, so a separate clone means separate outputs. This is the
     normal case and needs no configuration.
  3. <tmp>/mmws-<user>, if the repo is read-only.

The directory is created on demand. Nothing here is precious - it is all
regenerated by make_hull, make_scene and capture - so `out/` is gitignored.
"""

from __future__ import annotations

import os
import tempfile
from pathlib import Path


def output_dir() -> Path:
    env = os.environ.get("MMWS_OUT")
    if env:
        return _ensure(Path(env).expanduser())

    # Walk up to whatever directory holds tools/, which is the repo root.
    for parent in Path(__file__).resolve().parents:
        if (parent / "tools").is_dir():
            try:
                return _ensure(parent / "out")
            except OSError:
                break                      # read-only checkout; fall through

    user = os.environ.get("USER") or os.environ.get("USERNAME") or "anon"
    return _ensure(Path(tempfile.gettempdir()) / f"mmws-{user}")


def output(name: str) -> str:
    """Absolute path for a generated file, as a string for USD and open()."""
    return str(output_dir() / name)


def _ensure(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    return path
